import { chromium } from 'playwright';

const browser = await chromium.launch({ executablePath: '/usr/bin/chromium' });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });

await page.goto('http://localhost:4200/products', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/product-list.png', fullPage: true });
console.log('TITLE:', await page.title());
console.log('H1/H2 count check - card count:', await page.locator('.product-card').count());

// click first product
await page.locator('.product-card').first().click();
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/product-detail.png', fullPage: true });
console.log('URL after click:', page.url());

// add to cart
const addBtn = page.getByRole('button', { name: 'In den Warenkorb' });
if (await addBtn.count() > 0) {
  await addBtn.click();
  await page.waitForTimeout(500);
}
await page.goto('http://localhost:4200/cart', { waitUntil: 'networkidle' });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/cart.png', fullPage: true });

console.log('ERRORS:', JSON.stringify(errors, null, 2));
await browser.close();
EOF
